INSERT INTO measure VALUES (
  'colorado.gauge.lees_ferry.discharge', 'Colorado River at Lees Ferry — discharge', 'Daily mean discharge at USGS gauge 09380000, the Colorado River Compact point dividing the Upper and Lower Basins. Continuous daily record since 1921-10-01. Also serves as the real-time downstream cross-check on Glen Canyon Dam releases.',
  'VolumeFlowRate', 'cubic_foot_per_second', 'observed',
  'flow', 'interval_mean', 'P1D', 'water_year',
  'gauge', 'usgs.09380000',
  'USGS', 'Water Data OGC API', 'https://api.waterdata.usgs.gov/ogcapi/v0/collections/daily/items?monitoring_location_id=USGS-09380000&parameter_code=00060',
  'U.S. Geological Survey, National Water Information System via Water Data OGC API, site 09380000 Colorado River at Lees Ferry, AZ, parameter 00060. Accessed {access_date}.', 'mixed',
  'P1D', 48,
  '["Daily mean of a fluctuating hydropower-driven flow; sub-daily swings are large.","Never use legacy waterservices.usgs.gov (decommissioning) or discontinued site 09379910 for this reach."]'::jsonb,
  '[{"measure":"colorado.reservoir.powell.release_total","reason":"Interval-mean rate (cfs) vs. interval-total volume (AF/day), measured ~15 miles apart with Paria River inflow between. Convertible only with explicit rate→volume conversion and reach caveats.\n"}]'::jsonb
) ON CONFLICT (id) DO UPDATE SET
