INSERT INTO measure VALUES (
  'colorado.reservoir.mead.elevation', 'Lake Mead pool elevation', 'Water surface elevation of Lake Mead above mean sea level. The operative variable for shortage-tier determination (via projected January 1 elevation) and the critical thresholds at 1,075 / 1,050 / 1,025 ft (tiers), ~950 ft (minimum power pool), and 895 ft (dead pool).',
  'Length', 'foot', 'observed',
  'stage', 'instantaneous', 'P1D', 'water_year',
  'reservoir', 'usbr.lake_mead',
  'USBR', 'RISE', 'https://data.usbr.gov/rise/api/result?itemId=6123',
  'U.S. Bureau of Reclamation, RISE, Lake Mead pool elevation, catalog item 6123. Period of record from 1935-02-02. Accessed {access_date}.', 'provisional',
  'P1D', 36,
  '["Tier determination does not use current elevation: it uses the projected January 1 elevation from the August 24-Month Study. Displaying current elevation against tier thresholds requires that framing."]'::jsonb,
  '[{"measure":"colorado.reservoir.mead.storage","reason":"Elevation maps to storage only through the (re-surveyed, nonlinear) area-capacity table — never by linear scaling.\n"}]'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  label = EXCLUDED.label, description = EXCLUDED.description,
