  'P1D', 36,
  '["Storage is derived from elevation via an area-capacity table that is periodically re-surveyed; sedimentation shifts the curve over decades, so deep-historical storage values are not strictly comparable to modern ones."]'::jsonb,
  '[{"measure":"colorado.upper_basin.consumptive_use","reason":"Stock vs. flux. Same unit, different kind of quantity."},{"measure":"colorado.state.arizona.allocation","reason":"Allocation is a legal entitlement, not a measurement. Meaningful only as \"use vs. entitlement\" — never as a sum or a shared total.\n"}]'::jsonb
) ON CONFLICT (id) DO UPDATE SET
