INSERT INTO measure VALUES (
  'colorado.reservoir.powell.inflow_unregulated', 'Lake Powell unregulated inflow', 'Inflow to Lake Powell adjusted by Reclamation to remove the effects of upstream reservoir operations (Flaming Gorge, Blue Mesa, Navajo). The standard measure of what the Upper Basin actually produced, and the target variable of CBRFC seasonal forecasts.',
  'Volume', 'acre_foot', 'estimated',
  'flow', 'interval_total', 'P1D', 'water_year',
  'reservoir', 'usbr.lake_powell',
  'USBR', 'RISE', 'https://data.usbr.gov/rise/api/result?itemId=4301',
  'U.S. Bureau of Reclamation, RISE, Lake Powell unregulated inflow, catalog item 4301. Accessed {access_date}.', 'provisional',
  'P1D', 48,
  '["\"Unregulated\" is a computed abstraction, not a gauge reading — it removes upstream reservoir effects but not upstream consumptive use. It is NOT natural flow. Item id 4301 assumed from catalog research; verify item 4288 vs 4301 (regulated vs unregulated, af) on first ingest."]'::jsonb,
  '[{"measure":"colorado.gauge.lees_ferry.discharge_natural","reason":"Unregulated inflow removes reservoir operations only; naturalized flow also adds back upstream consumptive use. Different abstractions.\n"}]'::jsonb
) ON CONFLICT (id) DO UPDATE SET
