INSERT INTO measure VALUES (
  'colorado.reservoir.powell.release_total', 'Glen Canyon Dam total release', 'Total daily release volume from Glen Canyon Dam (powerplant plus bypass and spillway), i.e. Lake Powell outflow to the Grand Canyon reach and, ultimately, Lake Mead.',
  'Volume', 'acre_foot', 'observed',
  'flow', 'interval_total', 'P1D', 'water_year',
  'reservoir', 'usbr.lake_powell',
  'USBR', 'RISE', 'https://data.usbr.gov/rise/api/result?itemId=4354',
  'U.S. Bureau of Reclamation, RISE, Glen Canyon Dam total release (acre-feet), catalog item 4354. Accessed {access_date}.', 'provisional',
  'P1D', 36,
  '["Annual release volumes are set by tier rules but revisable mid-year: WY2026 was reduced from 7.48 to 6.00 MAF in April 2026 under SEIS ROD §6.E.","No active USGS gauge exists immediately below the dam (09379910 was discontinued 2004-08-02); Lees Ferry (09380000), ~15 miles downstream, is the independent observational cross-check."]'::jsonb,
  '[{"measure":"colorado.gauge.lees_ferry.discharge","reason":"Related but not identical: Lees Ferry is ~15 miles downstream with intervening Paria River inflow and reach effects, and is an interval-mean rate (cfs) rather than an interval-total volume.\n"}]'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  label = EXCLUDED.label, description = EXCLUDED.description,
  quantity_kind = EXCLUDED.quantity_kind, canonical_unit = EXCLUDED.canonical_unit,
