INSERT INTO measure VALUES (
  'colorado.snow.stations.swe', 'SNOTEL station snow water equivalent', 'Daily snow water equivalent at individual SNOTEL stations in the Upper Colorado Basin HUCs. The raw input to the basin percent-of-median rollup and the hydrology model''s SWE features. Station dimension carried in geography_id (one observation row per station per day).',
  'Length', 'millimeter', 'observed',
  'snowpack', 'instantaneous', 'P1D', 'water_year',
  'basin', 'colorado.upper_basin',
  'USDA-NRCS', 'AWDB REST', 'https://wcc.sc.egov.usda.gov/awdbRestApi/services/v1/data',
  'USDA Natural Resources Conservation Service, Air and Water Database (AWDB), SNOTEL network, element WTEQ. Accessed {access_date}.', 'provisional',
  'P1D', 48,
  '["Source unit is inches; converted to canonical millimeters at ingest.","Station set changes over time (new stations, discontinuations); the stations endpoint''s beginDate/endDate and HUC membership are synced as a dimension, not assumed static."]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  label = EXCLUDED.label, description = EXCLUDED.description,
  quantity_kind = EXCLUDED.quantity_kind, canonical_unit = EXCLUDED.canonical_unit,
